package difflines

import "errors"

func table(a, b []string) [][]int {
	n, m := len(a), len(b)
	t := make([][]int, n+1)
	for i := range t {
		t[i] = make([]int, m+1)
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if a[i] == b[j] {
				t[i][j] = t[i+1][j+1] + 1
			} else if t[i+1][j] >= t[i][j+1] {
				t[i][j] = t[i+1][j]
			} else {
				t[i][j] = t[i][j+1]
			}
		}
	}
	return t
}

func Diff(a, b []string) []string {
	t := table(a, b)
	n, m := len(a), len(b)
	i, j := 0, 0
	out := []string{}
	for i < n || j < m {
		switch {
		case i < n && j < m && a[i] == b[j]:
			out = append(out, "= "+a[i])
			i++
			j++
		case j == m || (i < n && t[i+1][j] >= t[i][j+1]):
			out = append(out, "- "+a[i])
			i++
		default:
			out = append(out, "+ "+b[j])
			j++
		}
	}
	return out
}

func ApplyScript(a, script []string) ([]string, error) {
	out := []string{}
	i := 0
	for _, e := range script {
		if len(e) < 2 || e[1] != ' ' || (e[0] != '=' && e[0] != '-' && e[0] != '+') {
			return nil, errors.New("bad script entry")
		}
		tag, text := e[0], e[2:]
		if tag == '+' {
			out = append(out, text)
			continue
		}
		if i >= len(a) || a[i] != text {
			return nil, errors.New("script does not match")
		}
		i++
		if tag == '=' {
			out = append(out, text)
		}
	}
	if i != len(a) {
		return nil, errors.New("script leaves lines unread")
	}
	return out, nil
}

func Distance(a, b []string) int64 {
	var n int64
	for _, e := range Diff(a, b) {
